static inline void ecg_conv1d_int8_f(const float *in, int L, int Ci,
                                     const int8_t *w_int8, const float *scales, const float *b,
                                     int Co, int K, float *out) {
    int pad = K / 2;
    for (int t = 0; t < L; t++) {
        for (int c_out = 0; c_out < Co; c_out++) {
            float sum = 0.0f;
            float scale = scales[c_out];
            int w_out_offset = c_out * K * Ci;
            for (int k = 0; k < K; k++) {
                int in_t = t + k - pad;
                if (in_t >= 0 && in_t < L) {
                    int in_base = in_t * Ci;
                    int w_base  = w_out_offset + k * Ci;
                    for (int c_in = 0; c_in < Ci; c_in++) {
                        sum += in[in_base + c_in] * ((float)w_int8[w_base + c_in] * scale);
                    }
                }
            }
            float val = sum + b[c_out];
            out[t * Co + c_out] = (val > 0.0f) ? val : 0.0f;
        }
    }
}

static inline void ecg_maxpool_f(const float *in, int L, int C, float *out) {
    int L_out = L / 2;
    for (int t = 0; t < L_out; t++) {
        int t0 = t * 2, t1 = t0 + 1;
        for (int c = 0; c < C; c++) {
            float v0 = in[t0 * C + c];
            float v1 = (t1 < L) ? in[t1 * C + c] : -1e30f;
            out[t * C + c] = (v0 > v1) ? v0 : v1;
        }
    }
}

static inline void ecg_gap_f(const float *in, int L, int C, float *out) {
    float invL = 1.0f / (float)L;
    for (int c = 0; c < C; c++) {
        float sum = 0.0f;
        for (int t = 0; t < L; t++) sum += in[t * C + c];
        out[c] = sum * invL;
    }
}

static inline void ecg_dense_int8_f(const float *in, int Ci,
                                    const int8_t *w_int8, const float *scales, const float *b,
                                    int Co, int relu, float *out) {
    for (int c_out = 0; c_out < Co; c_out++) {
        float sum = 0.0f;
        float scale = scales[c_out];
        int w_base = c_out * Ci;
        for (int c_in = 0; c_in < Ci; c_in++) {
            sum += in[c_in] * ((float)w_int8[w_base + c_in] * scale);
        }
        float val = sum + b[c_out];
        out[c_out] = (relu && val < 0.0f) ? 0.0f : val;
    }
}

static inline void tinyml_predict_int8(const int8_t *input,
                                       float probabilities[3],
                                       ecg_class_t *out_class) {
    uint32_t t0 = DWT->CYCCNT;
    for (int i = 0; i < 250; i++) {
        ecg_x0[i] = ((float)input[i] - (-128.0f)) * 0.003921568859368563f;
    }
    ecg_conv1d_int8_f(ecg_x0, 250, 1, ecg_c1w_int8, ecg_c1s, ecg_c1b, 16, 7, ecg_x1);
    ecg_maxpool_f(ecg_x1, 250, 16, ecg_x2);
    ecg_conv1d_int8_f(ecg_x2, 125, 16, ecg_c2w_int8, ecg_c2s, ecg_c2b, 32, 5, ecg_x3);
    ecg_maxpool_f(ecg_x3, 125, 32, ecg_x4);
    ecg_conv1d_int8_f(ecg_x4, 62, 32, ecg_c3w_int8, ecg_c3s, ecg_c3b, 32, 3, ecg_x5);
    ecg_gap_f(ecg_x5, 62, 32, ecg_xg);
    ecg_dense_int8_f(ecg_xg, 32, ecg_d1w_int8, ecg_d1s, ecg_d1b, 32, 1, ecg_xd1);
    ecg_dense_int8_f(ecg_xd1, 32, ecg_d2w_int8, ecg_d2s, ecg_d2b, 3, 0, ecg_xd2);

    float mx = ecg_xd2[0];
    if (ecg_xd2[1] > mx) mx = ecg_xd2[1];
    if (ecg_xd2[2] > mx) mx = ecg_xd2[2];
    float sm = 0.0f;
    for (int i = 0; i < 3; i++) {
        ecg_xd2[i] = expf(ecg_xd2[i] - mx);
        sm += ecg_xd2[i];
    }
    for (int i = 0; i < 3; i++) probabilities[i] = ecg_xd2[i] / sm;

    if (probabilities[1] > probabilities[0] && probabilities[1] > probabilities[2])
        *out_class = ECG_CLASS_VENTRICULAR;
    else if (probabilities[2] > probabilities[0])
        *out_class = ECG_CLASS_SUPRAVENTRICULAR;
    else
        *out_class = ECG_CLASS_NORMAL;

    watch_inferenceUs = (DWT->CYCCNT - t0) / (SystemCoreClock / 1000000UL);
}
